# Writes the timing sample: -Count files of ordinary Spar service code into obj/sample/, each about 110 lines, using
# Result in the ways an app does (returns, conversions, switches, TryGetValue, arrays filled in a loop, fields
# assigned in the constructor, LINQ, generic helpers). Writes a file only when its content changes.
# Usage: pwsh spikes/spar050/Sample/generate.ps1 [-Count 200]
param([int] $Count = 200)
$ErrorActionPreference = 'Stop'
$target = Join-Path $PSScriptRoot 'obj/sample'
New-Item -ItemType Directory -Force $target | Out-Null

$template = @'
// Generated by spikes/spar050/Sample/generate.ps1 (timing sample __N__). Ordinary Spar service code.
using Spar;

namespace Sample.Feature__N__;

/// <summary>Why a feature __N__ request failed.</summary>
public closed record Feature__N__Error
{
    public sealed record NotFound(string Id) : Feature__N__Error;

    public sealed record Conflict(string Id, long Version) : Feature__N__Error;
}

public sealed record Item__N__(string Id, long Version, IReadOnlyList<string> Tags);

public readonly record struct Attempt__N__(Result<Item__N__, Feature__N__Error> Outcome, int Number);

public sealed class Feature__N__Service
{
    private readonly Dictionary<string, Item__N__> _items = [];
    private readonly Result<Item__N__, Feature__N__Error> _missing;
    private Result<Item__N__, Feature__N__Error> _last;

    public Feature__N__Service(IEnumerable<Item__N__> seed)
    {
        foreach (var item in seed)
        {
            _items[item.Id] = item;
        }

        _missing = new Feature__N__Error.NotFound(string.Empty);
        _last = _missing;
    }

    public Result<Item__N__, Feature__N__Error> Last => _last;

    public Result<Item__N__, Feature__N__Error> Get(string id)
    {
        if (_items.TryGetValue(id, out var item))
        {
            _last = item;
            return item;
        }

        return new Feature__N__Error.NotFound(id);
    }

    public async Task<Result<Item__N__, Feature__N__Error>> UpdateAsync(Item__N__ item, CancellationToken cancellationToken = default)
    {
        await Task.Delay(0, cancellationToken);
        if (!_items.TryGetValue(item.Id, out var current))
        {
            return new Feature__N__Error.NotFound(item.Id);
        }

        if (current.Version != item.Version)
        {
            return new Feature__N__Error.Conflict(item.Id, current.Version);
        }

        var updated = item with { Version = item.Version + 1 };
        _items[item.Id] = updated;
        return updated;
    }

    public Result<Feature__N__Error> Delete(string id) =>
        _items.Remove(id) ? Result.Success : new Feature__N__Error.NotFound(id);

    public Result<Item__N__, Feature__N__Error>[] GetMany(IReadOnlyList<string> ids)
    {
        var results = new Result<Item__N__, Feature__N__Error>[ids.Count];
        for (var i = 0; i < results.Length; i++)
        {
            results[i] = Get(ids[i]);
        }

        return results;
    }

    public IEnumerable<Result<Item__N__, Feature__N__Error>> Search(string tag) =>
        _items.Values.Where(i => i.Tags.Contains(tag)).Select(i => (Result<Item__N__, Feature__N__Error>)i);

    public Attempt__N__ Retry(Attempt__N__ attempt) => attempt with { Number = attempt.Number + 1 };

    public static string Describe(Result<Item__N__, Feature__N__Error> result) => result switch
    {
        Item__N__ item => $"{item.Id} v{item.Version}",
        Feature__N__Error.NotFound e => $"missing {e.Id}",
        Feature__N__Error.Conflict e => $"conflict on {e.Id} at v{e.Version}",
    };

    public int Summarize(CancellationToken cancellationToken = default)
    {
        var first = _items.Values.FirstOrDefault();
        var counts = new int[4];
        var tags = _items.Values.SelectMany(i => i.Tags).Distinct().ToArray();
        foreach (var tag in tags)
        {
            cancellationToken.ThrowIfCancellationRequested();
            counts[tag.Length % counts.Length]++;
        }

        var errors = GetMany(tags).Count(r => r.IsError);
        var picked = Pick(errors > 0, _last, _missing);
        return counts.Sum() + errors + (first?.Tags.Count ?? 0) + (picked.IsSuccess ? 1 : 0);
    }

    private static T Pick<T>(bool first, T a, T b) => first ? a : b;
}
'@

$written = 0
for ($n = 1; $n -le $Count; $n++)
{
    $path = Join-Path $target ('Feature{0:D3}.cs' -f $n)
    $content = $template.Replace('__N__', $n.ToString('D3')).Replace("`r`n", "`n")
    if (-not (Test-Path $path) -or (Get-Content $path -Raw) -ne $content)
    {
        [System.IO.File]::WriteAllText($path, $content)
        $written++
    }
}

"$Count files in $target, $written written"
